function mock_product_image_tags($title, $category) {
  $title = strtolower($title);
  $rules = [
    'headphones|bluetooth|smartwatch' => 'headphones,electronics',
    'samsung|iphone|smartphone|feature phones|\bphone\b' => 'smartphone,product',
    'laptop|latitude|tablet|keyboard' => 'laptop,computer',
    'solar|charger|power bank|led|router|projector|printer|pos|barcode|card reader|tv box|console' => 'electronics,gadget',
    'abaya|dress|dresses|headscarf|skirts|modest' => 'modest,fashion',
    'shirts|t-shirt|uniform|tracksuits|jersey|workwear|blazers|jacket|knitwear' => 'clothing,apparel',
    'shoes|sandals|belts' => 'footwear,leather',
    'capulana|fabric|wrap' => 'african,fabric',
    'basket|baskets|woven|fiber|palm' => 'woven,basket',
    'wood|sculpture|mask|masks|tray|trays|soapstone|ornament' => 'wood,craft',
    'beaded|jewellery|keyrings' => 'beaded,jewelry',
    'ceramic|clay|pot|bowls|candle' => 'ceramic,craft',
    'macrame|cards|patchwork|rug|wall decor' => 'handmade,craft',
    'kitchen|appliance|air fryer|microwave|kettle|blender|cookware|containers|plates|water filter' => 'kitchen,appliance',
    'bedding|curtain|linen|rug|laundry|clock|shelving|storage|crates|cleaning' => 'home,interior',
    'sewing machine' => 'sewing,machine',
    'market stall|gazebo|display stand|signage|price tag|invoice|label|packaging|cash drawer|scale' => 'market,stall',
    'helmet|motorbike|delivery backpack' => 'delivery,motorcycle',
    'shopping bags|aprons|chairs|desk fan|barrier rope|document folder' => 'small,business',
  ];

  foreach ($rules as $pattern => $tags) {
    if (preg_match('/' . $pattern . '/', $title)) return $tags;
  }

  return [
    'electronics' => 'electronics,product',
    'clothing' => 'clothing,fashion',
    'handicrafts' => 'handmade,craft',
    'household' => 'home,goods',
    'other' => 'business,supplies',
  ][$category] ?? 'market,product';
}

